void test_attr_macro__recursive_macro_resolves ( void ) { const char * value ; cl_git_pass ( git_attr_add_macro ( g_repo , "expandme" , "key=value" ) ) ; cl_git_pass ( git_attr_add_macro ( g_repo , "macro" , "expandme" ) ) ; cl_git_rewritefile ( "empty_standard_repo/.gitattributes" , "file.txt macro" ) ; cl_git_pass ( git_attr_get ( & value , g_repo , 0 , "file.txt" , "key" ) ) ; cl_assert_equal_s ( value , "value" ) ; } 